steps.script:
var main = tree.current_scene
for i in range(main.army_options.size()):
	if str(main.army_options[i].id) == "MULTI_DET_E2E_Custodes":
		return i
return -1

var main = tree.current_scene
var dd: OptionButton = main.p1_disposition_dropdown
var D = PrimaryMissionData11e.DISPOSITIONS
var sel := str(D[dd.selected])
var off: Array = []
for i in range(dd.item_count):
	if dd.is_item_disabled(i):
		off.append(str(D[i]))
print("[multi-det] P1 disposition=", sel, " disabled=", off, " tooltip=", dd.tooltip_text)
return sel == "reconnaissance" and "take_and_hold" in off and "purge_the_foe" in off and "priority_assets" in off and not "disruption" in off

var raw = ArmyListManager.cloud_army_cache.get("MULTI_DET_E2E_Custodes", {})
var f = raw.get("faction", {})
var dp := 0
for d in raw.get("detachments", []):
	dp += int(d.get("dp_cost", 0))
print("[multi-det] faction=", f.get("detachment"), " all=", f.get("detachments"), " dp=", dp)
return str(f.get("detachment")) == "Lions of the Emperor" and f.get("detachments", []) == ["Lions of the Emperor", "Solar Watch", "Null Maiden Vigil"] and dp == 3

var raw = ArmyListManager.cloud_army_cache.get("MULTI_DET_E2E_Custodes", {})
var v: Dictionary = ArmyListManager.validate_army_construction_11e(raw)
print("[multi-det] construction warnings=", v.warnings)
for w in v.warnings:
	if str(w).contains("DP") or str(w).contains("is not a"):
		return str(w)
return true

for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if int(u.get("owner", 0)) == 1 and str(u.meta.get("name", "")) == "Shield-Captain":
		GameState.state.meta["_mdet_sc"] = uid
		print("[multi-det] ", uid, " enh=", u.meta.get("enhancements", []))
		return str(u.meta.get("enhancements", [])).contains("Sally Forth")
return "no Shield-Captain"

var f = GameState.state.factions["1"]
var fam = tree.root.get_node("FactionAbilityManager")
print("[multi-det] factions[1].detachments=", f.get("detachments"), " fam=", fam.get_player_detachments(1))
return f.get("detachments", []) == ["Lions of the Emperor", "Solar Watch", "Null Maiden Vigil"] and fam.player_has_detachment(1, "Solar Watch") and fam.player_has_detachment(1, "Null Maiden Vigil")

var sm = tree.root.get_node("StratagemManager")
var names: Array = []
for sid in sm._player_faction_stratagems.get("1", []):
	names.append(str(sm.stratagems.get(sid, {}).get("name", "")).to_upper())
print("[multi-det] P1 faction stratagems: ", names)
return "UNLEASH THE LIONS" in names and "INEXORABLE" in names and "PURGATION SWEEP" in names

var k = load("res://scripts/codex/custodes/CustodesKatah.gd")
print("[multi-det] favoured ka'tah P1 = ", k.favoured_katah(1))
return k.favoured_katah(1)

var ds = tree.current_scene.get_node("DatasheetModal")
for l in ds.find_children("*", "Label", true, false):
	if str(l.text).begins_with("Enhancement:"):
		return l.text.contains("Sally")
return false
